```csharp
using UnityEngine;

public class GameManager : MonoBehaviour
{
    public int rows = 8;
    public int columns = 8;
    public GameObject[] colors; // Array of color Sprites

    private GameObject[,] tiles; // 2D array to store tiles
    private int score = 0;

    void Start()
    {
        // Initialize the game board
        tiles = new GameObject[rows, columns];
        for (int i = 0; i < rows; i++)
        {
            for (int j = 0; j < columns; j++)
            {
                GameObject tile = Instantiate(colors[Random.Range(0, colors.Length)], new Vector3(i, j, 0), Quaternion.identity);
                tiles[i, j] = tile;
            }
        }
    }

    void Update()
    {
        // Check for matches
        CheckForMatches();

        // Update score
        scoreText.text = "Score: " + score;
    }

    void CheckForMatches()
    {
        // Iterate through the game board
        for (int i = 0; i < rows; i++)
        {
            for (int j = 0; j < columns; j++)
            {
                // Check for matching tiles
                if (CheckForMatch(i, j))
                {
                    // Remove matched tiles
                    RemoveTile(i, j);
                }
            }
        }
    }

    bool CheckForMatch(int row, int column)
    {
        // Check horizontally
        if (column < columns - 2)
        {
            if (tiles[row, column].tag == tiles[row, column + 1].tag && tiles[row, column + 1].tag == tiles[row, column + 2].tag)
            {
                return true;
            }
        }

        // Check vertically
        if (row < rows - 2)
        {
            if (tiles[row, column].tag == tiles[row + 1, column].tag && tiles[row + 1, column].tag == tiles[row + 2, column].tag)
            {
                return true;
            }
        }

        return false;
    }

    void RemoveTile(int row, int column)
    {
        // Remove the matched tiles
        GameObject tile = tiles[row, column];
        Destroy(tile);
    }
}
```
