        onChange={handleChange}
        placeholder="Type something"
      />
      {filteredSuggestions.map((suggestion, index) => (
        <div
          key={index}
          onClick={() => handleSelect(suggestion)}
          style={{
            background: 'white',
            padding: '10px',
            border: '1px solid lightgray',
          }}
        >
          {suggestion}
        </div>
      ))}
    </div>
  );
};

export default Autocomplete;
